def seed_database():
    print("==========================================================")
    print("  AgroGuide Database Seed Script (500+ Structured Crops)  ")
    print("==========================================================")

    # Ensure tables are created
    Base.metadata.create_all(bind=engine)
    db: Session = SessionLocal()

    try:
        # 1. Seed Demo Users
        print("\n[1/6] Seeding Demo Users...")
        admin_user = db.query(User).filter(User.email == "admin@agroguide.com").first()
        if not admin_user:
            admin_user = User(
                name="AgroGuide Admin",
                email="admin@agroguide.com",
                phone="+91 98765 00001",
                password_hash=get_password_hash("admin123"),
                role="Admin",
                preferred_language="en",
                state="Kerala",
                district="Palakkad",
                is_active=True
            )
            db.add(admin_user)
            print("  [OK] Admin User created: admin@agroguide.com / admin123")
        else:
            admin_user.role = "Admin"
            admin_user.password_hash = get_password_hash("admin123")
            admin_user.is_active = True
            print("  [OK] Admin User updated: admin@agroguide.com / admin123")

        farmer_user = db.query(User).filter(User.email == "farmer@agroguide.com").first()
        if not farmer_user:
            farmer_user = User(
                name="Sreeraj Menon",
                email="farmer@agroguide.com",
                phone="+91 98765 43210",
                password_hash=get_password_hash("farmer123"),
                role="Farmer",
                preferred_language="en",
                state="Kerala",
                district="Palakkad",
                is_active=True
            )
            db.add(farmer_user)
            db.flush()

            # Create Farm Profile
            farm = Farm(
                user_id=farmer_user.id,
                farm_name="Menon Greenfield Farms",
                farm_size=3.5,
                soil_type="Alluvial",
                soil_ph=6.5,
                irrigation_type="Canal / River",
                location="Palakkad, Kerala",
                current_season="Kharif",
                current_crops="Rice (Paddy), Banana (Nendran)"
            )
            db.add(farm)
            print("  [OK] Demo Farmer created: farmer@agroguide.com / farmer123")

        pro_user = db.query(User).filter(User.email == "expert@agroguide.com").first()
        if not pro_user:
            pro_user = User(
                name="Dr. Radhakrishnan Nair",
                email="expert@agroguide.com",
                phone="+91 94471 23456",
                password_hash=get_password_hash("expert123"),
                role="Agricultural Professional",
                preferred_language="en",
                state="Kerala",
                district="Thrissur",
                is_active=True
            )
            db.add(pro_user)
            print("  [OK] Expert User created: expert@agroguide.com / expert123")

        db.commit()

        # 2. Seed 500+ Crops
        print(f"\n[2/6] Seeding {len(CROPS_DATA)} Structured Crops...")
        existing_crops = db.query(Crop.name).all()
        existing_names = {c[0] for c in existing_crops}

        added_crops_count = 0
        for crop_data in CROPS_DATA:
            if crop_data["name"] not in existing_names:
                crop = Crop(**crop_data)
                db.add(crop)
                added_crops_count += 1
                existing_names.add(crop_data["name"])

        db.commit()
        total_crops = db.query(Crop).count()
        print(f"  [OK] Added {added_crops_count} new crops. Total Crops in Database: {total_crops}")

        # 3. Seed Pests & Diseases
        print("\n[3/6] Seeding Pest & Disease Knowledge Catalog...")
        for pest in PESTS_DATA:
            crop_obj = db.query(Crop).filter(Crop.name == pest["crop_name"]).first()
            crop_id = crop_obj.id if crop_obj else None
            existing = db.query(CropPest).filter(CropPest.name == pest["name"]).first()
            if not existing:
                db.add(CropPest(
                    crop_id=crop_id,
                    crop_name=pest["crop_name"],
                    name=pest["name"],
                    symptoms=pest["symptoms"],
                    prevention=pest["prevention"],
                    management=pest["management"],
                    professional_guidance=pest["professional_guidance"]
                ))

        for disease in DISEASES_DATA:
            crop_obj = db.query(Crop).filter(Crop.name == disease["crop_name"]).first()
            crop_id = crop_obj.id if crop_obj else None
            existing = db.query(CropDisease).filter(CropDisease.name == disease["name"]).first()
            if not existing:
                db.add(CropDisease(
                    crop_id=crop_id,
                    crop_name=disease["crop_name"],
                    name=disease["name"],
                    symptoms=disease["symptoms"],
                    prevention=disease["prevention"],
                    management=disease["management"],
                    professional_guidance=disease["professional_guidance"]
                ))
        db.commit()
        print(f"  [OK] Pests & Diseases seeded successfully.")

        # 4. Seed Market Prices
        print("\n[4/6] Seeding Demo Mandi Market Records...")
        for m in MARKET_PRICES_DATA:
            crop_obj = db.query(Crop).filter(Crop.name.ilike(f"%{m['crop_name'].split('(')[0].strip()}%")).first()
            crop_id = crop_obj.id if crop_obj else None
            existing = db.query(MarketPrice).filter(
                MarketPrice.crop_name == m["crop_name"],
                MarketPrice.market_name == m["market_name"]
            ).first()
            if not existing:
                db.add(MarketPrice(
                    crop_id=crop_id,
                    crop_name=m["crop_name"],
                    market_name=m["market_name"],
                    location=m["location"],
                    price=m["price"],
                    min_price=m["min_price"],
                    max_price=m["max_price"],
                    unit=m["unit"],
                    trend=m["trend"],
                    trend_percentage=m["trend_percentage"],
                    is_demo=True
                ))
        db.commit()
        print(f"  [OK] Market prices seeded successfully.")

        # 5. Seed Professionals
        print("\n[5/6] Seeding Agricultural Professionals...")
        for prof in PROFESSIONALS_DATA:
            existing = db.query(Professional).filter(Professional.name == prof["name"]).first()
            if not existing:
                db.add(Professional(**prof))
        db.commit()
        print("  [OK] Agricultural Experts seeded successfully.")

        # 6. Seed Community Forum Posts
        print("\n[6/6] Seeding Farmer Community Discussions...")
        if farmer_user:
            existing_post = db.query(CommunityPost).filter(CommunityPost.title.ilike("%paddy crop rotation%")).first()
            if not existing_post:
                post1 = CommunityPost(
                    user_id=farmer_user.id,
                    title="Best crop rotation after Mundakan Paddy in Palakkad?",
                    content="Hello fellow farmers, we are finishing our Mundakan paddy harvest in Palakkad next month. What is the most profitable green gram or vegetable rotation given current canal water levels?",
                    category="Crop",
                    likes_count=8,
                    comments_count=2,
                    is_pinned=True
                )
                db.add(post1)
                db.flush()

                c1 = Comment(
                    post_id=post1.id,
                    user_id=admin_user.id if admin_user else farmer_user.id,
                    content="Green Gram (Cherupayar) or Black Gram (Urad) works exceptionally well in rice fallows. It enriches residual soil nitrogen for the next season with minimal irrigation!"
                )
                db.add(c1)

                post2 = CommunityPost(
                    user_id=farmer_user.id,
                    title="Organic management for pseudostem borer in Nendran banana",
                    content="Noticing some transparent gum oozing from lower banana pseudostems. Anyone had success using Beauveria bassiana traps?",
                    category="Pest",
                    likes_count=12,
                    comments_count=1,
                    is_pinned=False
                )
                db.add(post2)

                db.commit()
                print("  [OK] Sample Community forum discussions seeded.")

        print("\n==========================================================")
        print("   DATABASE SEED COMPLETED SUCCESSFULLY! (500+ CROPS)   ")
        print("==========================================================\n")

    except Exception as e:
        db.rollback()
        print(f"\n[ERROR] Seeding failed: {str(e)}")
        raise e
    finally:
        db.close()


if __name__ == "__main__":
    seed_database()
